// Toggle filters button label:
// - filters visible => "Nascondi ricerche"
// - filters hidden  => "Cerca"
window.ibSetToggleFiltersButtonLabel = function ($btn, tableId) {
    if (!$btn || !$btn.length || !tableId)
        return;

    const $wrapper = $('#' + tableId + '_wrapper');
    const $headerFilterRow = $wrapper.find('thead tr.columns').first();

    const filtersHidden = $headerFilterRow.length ? $headerFilterRow.hasClass('uk-hidden') : false;

    const labelHtml = filtersHidden
        ? '<i class="fa-solid fa-magnifying-glass"></i> Cerca'
        : '<i class="fa-solid fa-filter-circle-xmark"></i> Nascondi ricerche';

    const tooltip = filtersHidden
        ? 'Mostra le celle di ricerca'
        : 'Nascondi le celle di ricerca';

    $btn
        .attr('uk-tooltip', 'title: ' + tooltip + '; pos: top')
        .html(labelHtml);

    // keep styling consistent with previous behavior (primary when filters are hidden)
    $btn.toggleClass('uk-button-primary', !!filtersHidden);
};

// Sync "clear filters" button highlight:
// - should be red ONLY when custom header/footer filters are actually active
// - uses the same signal as filtering.min.js ( presence of `.filter-filled` )
window.ibSyncClearFiltersButtonForTable = function (tableId) {
    if (!tableId)
        return;

    const table = document.querySelector("table[data-realid='" + tableId + "']");
    if (!table)
        return;

    const hasActive =
        table.querySelectorAll('.columns .filter-filled').length > 0;

    $(table)
        .closest('.dataTables_wrapper, .dt-container')
        .find('.clearfilters')
        .toggleClass('ib-has-active-filters', hasActive)
        // legacy: drawCallback used uk-button-danger based on info text; keep classes consistent
        .toggleClass('uk-button-danger', hasActive);
};

$(document).ready(function($)
{
    // Track last navigation source (keyboard vs pointer)
    window.__dtLastNav = { type: null, ts: 0, key: null };

    $(document).on('keydown', function (e) {
        const keys = ['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Tab','Enter'];
        if (keys.includes(e.key)) {
            window.__dtLastNav = { type: 'keyboard', ts: Date.now(), key: e.key };
        }
    });

    $(document).on('mousedown pointerdown touchstart', function () {
        window.__dtLastNav = { type: 'pointer', ts: Date.now(), key: null };
    });

    $('body').on('mouseenter', '.dt-scroll-body table.wannabedatatable', function (e)
    {
        if (! $(this).data('adjusted'))
        {
            let table = $(this).DataTable();

            table.columns.adjust().draw();

            $(this).data('adjusted', true);
        }
    });

    $('body').on('click', '.ib-dt-alert-cell', function (e)
    {
        UIkit.modal.dialog($(this).attr('title'));
    });

    window.ibInitializeDatatables = function (container = document)
    {
        $(container)
            .filter('.wannabedatatable')
            .add($(container).find('.wannabedatatable'))
            .each(function()
    {
        if ($.fn.dataTable.isDataTable(this))
            return;

        let tableId = $(this).attr('id');
        let columnDefs = window[tableId + 'columnDefs'];
        let rowReorder = window[tableId + 'rowReorder'];
        let options = window[tableId + 'options'];
        let buttons = window[tableId + 'buttons'];
		let hasSorting = window[tableId + 'hasSorting'];
		let nullLastColumns = window[tableId + 'nullLastColumns'] || [];

        let settings = {
            processing: true,
            orderCellsTop: true,
            searchDelay: 450,
            lengthMenu: [[10, 25, 50, 100, 250, 500, -1], [10, 25, 50, 100, 250, 500, "All"]],
            columnDefs : columnDefs,
            rowReorder : rowReorder,
            buttons: {
                dom: {
                    button: {
                        className: 'uk-button uk-button-small'
                    }
                },
                buttons: buttons
            },
            initComplete: function ()
            {
                if (typeof $('#' + tableId).data('sticky') !== 'undefined')
                    UIkit.sticky($('#' + tableId + '_wrapper').find('.' + $('#' + tableId).data('sticky')), {bottom: true});

                // this.api().applyTableFilters();

                if(typeof window[tableId + 'options'] !== 'undefined')
                    if(typeof window[tableId + 'options'].captionText !== 'undefined')
                        $('#' + tableId + '_wrapper .tablecaption').html(window[tableId + 'options'].captionText);

                $('#' + tableId + '_wrapper .dataTables_length select').addClass('uk-select');
                $('#' + tableId + '_filter input').addClass('uk-input').attr('placeholder', window[tableId + 'options'].language.searchPlaceholder);

                // Apply persisted UI settings (main header / filters visibility)
                try {
                    const ui = (window.__ibDatatableUiSettings && window.__ibDatatableUiSettings[tableId]) ? window.__ibDatatableUiSettings[tableId] : {};
                    const $wrapper = $('#' + tableId + '_wrapper');

                    // main header
                    if (ui && (ui.mainHeaderHidden === true || ui.mainHeaderHidden === 1 || ui.mainHeaderHidden === '1'))
                    {
                        const $rows = $wrapper.find('thead tr.mainheader');
                        $rows.addClass('uk-hidden');
                        $wrapper.find('button.togglemainheader').addClass('uk-button-primary');
                    }

                    // filters (both header and footer)
                    if (ui && (ui.filtersHidden === true || ui.filtersHidden === 1 || ui.filtersHidden === '1'))
                    {
                        $wrapper.find('thead tr.columns').addClass('uk-hidden');
                        $wrapper.find('tfoot tr.columns').addClass('uk-hidden');
                    }
                } catch (e) {}

                // sync filters toggle button label after applying persisted UI settings
                try {
                    if (typeof window.ibSetToggleFiltersButtonLabel === 'function') {
                        window.ibSetToggleFiltersButtonLabel($('#' + tableId + '_wrapper').find('button.togglefilters'), tableId);
                    }
                } catch (e) {}

                // Utils button: badge con conteggio colonne campo nascoste
                try {
                    const dtApi = this.api();
                    const refreshUtilsHiddenBadge = function () {
                        if (typeof window.ibDtUpdateUtilsHiddenBadge === 'function')
                            window.ibDtUpdateUtilsHiddenBadge(dtApi);
                    };
                    refreshUtilsHiddenBadge();
                    setTimeout(refreshUtilsHiddenBadge, 0);
                    dtApi.on('column-visibility.dt', refreshUtilsHiddenBadge);
                    dtApi.on('draw.dt', refreshUtilsHiddenBadge);
                } catch (e) {}




                //TODO TODO TODO SISTEMARE
                //questo è per filtrare da parametri in get.... fa un po' schifo ma funziona
                const queryString = window.location.search;
                const urlParams = new URLSearchParams(queryString);

                var entries = urlParams.entries();
                var fields = [];

                for(var entry of entries)
                {
                    var pieces = entry[0].split('-');

                    if(pieces[0] == 'dtFilter')
                    {
                        fields.push(pieces[1]);

                        $('#' + tableId).find('th.' + pieces[1] + ' input').val(entry[1]);
                    }
                }

                setTimeout(dtFilterUrlParameters, 2, fields);
                //questo è per filtrare da parametri in get.... fa un po' schifo ma funziona
                //FINE TODO TODO TODO SISTEMARE
            }
        };

        jQuery.extend(settings, options);

		/*
		 * hasSorting controls only the user's ability to change the order. When it
		 * is disabled, FieldsGroupParameters is the sole source of the table order.
		 */
		if (hasSorting === false)
		{
			const configuredOrder = (Array.isArray(options.order) ? options.order : []).map(function(order)
			{
				return [order[0], String(order[1]).toLowerCase()];
			});
			const configuredInitComplete = settings.initComplete;

			// Prevent DataTables from falling back to its implicit first-column order.
			settings.order = configuredOrder;

			settings.initComplete = function()
			{
				if (typeof configuredInitComplete === 'function')
					configuredInitComplete.apply(this, arguments);

				// Reapply after Ajax/state restoration, using the same API path as a click.
				this.api().order(configuredOrder).draw(false);
			};
		}

		const isNullLastValue = function(value)
		{
			return value === null || value === false ||
				typeof value === 'undefined' || value === '';
		};

		const applyNullLastOrdering = function(dataTableSettings)
		{
			if (! nullLastColumns.length || ! Array.isArray(dataTableSettings.aiDisplay))
				return;

			const api = new $.fn.dataTable.Api(dataTableSettings);
			const activeOrder = api.order();
			const displayIndexes = dataTableSettings.aiDisplay.slice();

			const getValue = function(rowIndex, columnIndex)
			{
				return api.cell(rowIndex, columnIndex).data();
			};

			const precedingValuesMatch = function(leftRow, rightRow, orderPosition)
			{
				for (let position = 0; position < orderPosition; position++)
				{
					const precedingColumn = activeOrder[position][0];

					if (getValue(leftRow, precedingColumn) !== getValue(rightRow, precedingColumn))
						return false;
				}

				return true;
			};

			activeOrder.forEach(function(order, orderPosition)
			{
				const columnIndex = Number(order[0]);

				if (! nullLastColumns.map(Number).includes(columnIndex))
					return;

				let groupStart = 0;

				while (groupStart < displayIndexes.length)
				{
					let groupEnd = groupStart + 1;

					while (groupEnd < displayIndexes.length && precedingValuesMatch(
						displayIndexes[groupStart], displayIndexes[groupEnd], orderPosition
					))
						groupEnd++;

					const group = displayIndexes.slice(groupStart, groupEnd);
					const values = [];
					const emptyValues = [];

					group.forEach(function(rowIndex)
					{
						if (isNullLastValue(getValue(rowIndex, columnIndex)))
							emptyValues.push(rowIndex);
						else
							values.push(rowIndex);
					});

					displayIndexes.splice(groupStart, group.length, ...values, ...emptyValues);
					groupStart = groupEnd;
				}
			});

			dataTableSettings.aiDisplay.splice(
				0,
				dataTableSettings.aiDisplay.length,
				...displayIndexes
			);
		};

        const userPreDrawCallback = settings.preDrawCallback;

        settings.preDrawCallback = function (settings) {
            const $table = $(this.api().table().node());
            const $inlineCreateRow = $table
                .children('tbody')
                .children('tr.ib-datatable-inline-create-row');

            if (typeof userPreDrawCallback === 'function')
            {
                const result = userPreDrawCallback.call(this, settings);

                if (result === false)
                    return false;
            }

			applyNullLastOrdering(settings);

            if ($inlineCreateRow.length)
            {
                const activeElement = document.activeElement;
                let focusState = null;

                if (activeElement && $inlineCreateRow[0].contains(activeElement))
                {
                    focusState = {
                        element: activeElement,
                        selectionStart: activeElement.selectionStart,
                        selectionEnd: activeElement.selectionEnd,
                    };
                }

                settings._ibInlineCreateFocus = focusState;
                settings._ibInlineCreateRow = $inlineCreateRow.detach();
            }

            return true;
        };

        const userDrawCallback = settings.drawCallback;

        settings.drawCallback = function (settings) {
            // 1) callback del chiamante (quella che hai visto nel log)
            if (typeof userDrawCallback === 'function') {
                userDrawCallback.call(this, settings);
            }

            // 2) callback “core” registrata su Api
            this.api()._drawCallback();

            window.refreshAllTableFieldsParameters();

            const $wrapper = $(this.api().table().container());
            const $inlineCreateRow = settings._ibInlineCreateRow;

            if ($wrapper.hasClass('ib-datatable-inline-create-locked')
                && $inlineCreateRow
                && $inlineCreateRow.length)
            {
                const $tbody = $(this.api().table().node()).children('tbody');

                $tbody.children('tr')
                    .has('td.dt-empty, td.dataTables_empty')
                    .addClass('uk-hidden ib-datatable-inline-create-empty-row');
                $tbody.prepend($inlineCreateRow);

                const focusState = settings._ibInlineCreateFocus;

                if (focusState && focusState.element)
                {
                    focusState.element.focus();

                    if (typeof focusState.element.setSelectionRange === 'function'
                        && typeof focusState.selectionStart === 'number'
                        && typeof focusState.selectionEnd === 'number')
                    {
                        focusState.element.setSelectionRange(
                            focusState.selectionStart,
                            focusState.selectionEnd
                        );
                    }
                }
            }
        };

        window['table' + tableId] = $(this).DataTable(settings)
            .on('key-blur', function ( e, datatable, cell ) {
                $(cell.node()).find('input').blur();
                $(cell.node()).find('select').blur();
            }).on('preDraw', function () {
                startTime = new Date().getTime();
            }).on('row-reorder', function (e, diff, edit)
            {
                let tableNode = $(e.target);
                let table = tableNode.DataTable({retrieve: true});
                let rowIdColumnIndex = tableNode.data('rowid');

                if(typeof rowIdColumnIndex == 'undefined')
                {
                    alert('Manca data-rowid sulla tabella');
                    // return false;
                }

                let storeSortingUrl = tableNode.data('storemasssortingurl');

                if(typeof storeSortingUrl == 'undefined')
                {
                    console.log('Manca data-sortingurl sulla tabella');
                    // return false;
                }

                window.changedSorting = true;

                var sortingData = new Object();

                for ( var i=0, ien=diff.length ; i<ien ; i++ )
                {
                    var rowData = table.row( diff[i].node ).data();

                    var rowId = rowData[rowIdColumnIndex];
                    var newPosition = diff[i].newData;

                    sortingData[rowId] = newPosition;
                }

                if(storeSortingUrl)
                    $.ajax({
                        url: storeSortingUrl,
                        type: 'POST',
                        headers: window.ibGetDatatableBroadcastHeaders(tableNode[0]),
                        data: {
                            indexes : sortingData
                        },
                        error: function(response, message, asd)
                        {
                            alert('Error');
                        },
                        success: function(response)
                        {
                            $('.ibfetcherbuttons .refresh').click();

                            window.addSuccessNotification('Reorder done');
                        }
                    });
            })
            .on('key-focus', function ( e, datatable, cell ) {

                const rowIdx = cell.index().row;
                const rowNode = datatable.row(rowIdx).node();

                if (!rowNode) return;

// rimuovi il focus dalle altre righe della stessa tabella
                $(datatable.table().body())
                    .find('tr.ib-row-focused')
                    .not(rowNode)
                    .removeClass('ib-row-focused');

// toggle sulla riga corrente
                rowNode.classList.toggle('ib-row-focused');

                setTimeout(function () {

                    // 1) select-all ONLY if we arrived here via keyboard navigation very recently
                    const nav = window.__dtLastNav || {};
                    if (nav.type !== 'keyboard') return;
                    if (nav.ts && (Date.now() - nav.ts > 600)) return; // stale: ignore

                    const $node = $(cell.node());
                    const $field = $node.find('input, textarea').first();

                    if ($field.length) {
                        const el = $field[0];

                        // 2) don't override if user is already editing that same field
                        if (document.activeElement === el) return;

                        // 3) avoid types where select() is pointless / annoying
                        const type = String($field.attr('type') || '').toLowerCase();
                        if (['checkbox', 'radio', 'file', 'button', 'submit'].includes(type)) {
                            $field.trigger('focus');
                            return;
                        }

                        el.focus();

                        if (typeof el.select === 'function') {
                            el.select();
                        }

                        return;
                    }

                    // select: just focus
                    const $select = $node.find('select').first();
                    if ($select.length) $select.trigger('focus');

                }, 50);

            });


        new $.fn.dataTable.Buttons( window['table' + tableId], {
            buttons: []
        } );

        window['table' + tableId].buttons( 1, null ).container().appendTo(
            window['table' + tableId].table().container()
        );

            });
    };

    window.ibFetcherInit = function (container)
    {
        window.ibInitializeDatatables(container);
        $(document).trigger('ibFetcher:initialized', [container]);
    };

    window.ibInitializeDatatables(document);


    /**
     * gestione dell'ordinamento delle colonne START
     */
    function toggle(dir) { return dir === 'asc' ? 'desc' : 'asc'; }

    function drawPreservingHorizontalScroll(table)
    {
        const $wrapper = $(table.table().container());
        const scrollPositions = $wrapper
            .find('.dt-scroll-body, .dataTables_scrollBody')
            .map(function ()
            {
                return {
                    element: this,
                    scrollLeft: this.scrollLeft
                };
            })
            .get();

        if (! scrollPositions.length)
            return table.draw();

        const restoreHorizontalScroll = function ()
        {
            scrollPositions.forEach(function (scrollPosition)
            {
                const maxScrollLeft = Math.max(
                    0,
                    scrollPosition.element.scrollWidth - scrollPosition.element.clientWidth
                );

                scrollPosition.element.scrollLeft = Math.min(
                    scrollPosition.scrollLeft,
                    maxScrollLeft
                );
            });
        };

        // DataTables and its extensions can finish recalculating scrollX after
        // the draw event, so restore once on the next paint and once afterwards.
        $(table.table().node()).one('draw.dt.ibPreserveHorizontalScroll', function ()
        {
            window.requestAnimationFrame(restoreHorizontalScroll);
            window.setTimeout(restoreHorizontalScroll, 50);
        });

        return table.draw();
    }

    function toggleSort(table, colIndex, shiftKey)
    {
        const cur = table.order();                 // es: [[0,'asc'],[2,'desc']]

        if (shiftKey) {
            // ---- SHIFT + click: mantieni il resto ----
            const others = cur.filter(([i]) => i !== colIndex);
            const found  = cur.find(([i]) => i === colIndex);

            let next;
            if (!found) {
                // non c'era: aggiungila in coda come priorità più bassa
                next = [...cur, [colIndex, 'asc']];
            } else {
                // c'era: toggla solo la sua direzione, mantieni le altre
                next = [...others, [colIndex, toggle(found[1])]];
            }
            drawPreservingHorizontalScroll(table.order(next));

        } else {
            // ---- Click normale: SOLO questa colonna ----
            const found = cur.find(([i]) => i === colIndex);
            const dir = found ? toggle(found[1]) : 'asc';
            drawPreservingHorizontalScroll(table.order([[colIndex, dir]]));
        }
    }


    $('.changesorting').click(function (e)
    {
        e.stopPropagation();

        let th = $(this).closest('th');
        let colIndex = $(th).data('column');
        let datatable = window.__getDataTable(this);

        toggleSort(datatable, colIndex, e.shiftKey);
    });

    $('.changesorting').keydown(function (e)
    {
        if (e.key !== 'Enter' && e.key !== ' ')
            return;

        e.preventDefault();
        $(this).trigger('click');
    });

    /**
     *
     * gestione dell'ordinamento delle colonne END
     */






    $('body').on( 'mouseenter', '.uk-text-truncate', function(){
        var $this = $(this);

        if(this.offsetWidth < this.scrollWidth && !$this.attr('title')){
            $this.attr('title', $this.text());
            UIkit.tooltip($this, {title: $this.text()}).show();
        }
    });



});   
